import re,os,json
exec(open('/dev/stdin').read()) if False else None
d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
    k,h,w=m[1],int(m[2]),int(m[3])
    rows=[r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k]=[[int(x) for x in r] for r in rows]
print(sorted(G))
gi,go=G['Demo pair 1 input'],G['Demo pair 1 output']
# find each non-0,5 color's cell positions in input
from collections import defaultdict
pos=defaultdict(list)
for i,row in enumerate(gi):
    for j,v in enumerate(row):
        if v not in (0,5): pos[v].append((i,j))
for c,ps in sorted(pos.items()): print(c,ps)
# output positions
op=defaultdict(list)
for i,row in enumerate(go):
    for j,v in enumerate(row):
        if v!=0: op[v].append((i,j))
for c,ps in sorted(op.items()): print('out',c,ps)

def f(g):
    H=len(g)//3
    out=[[0]*H for _ in range(H)]
    for bi in range(H):
        for bj in range(H):
            vs={g[i][j] for i in range(bi*3,bi*3+3) for j in range(bj*3,bj*3+3) if g[i][j] not in (0,5)}
            if len(vs)==1: out[bi][bj]=vs.pop()
    return out
print(f(gi)==go)
print(json.dumps(f(G['Test input'])))

